#define RB_DEVICES_N ((int)(sizeof(RB_DEVICES) / sizeof(RB_DEVICES[0])))

int rb_device_count(void)
{
    return RB_DEVICES_N;
}

const rb_device *rb_device_at(int index)
{
    if (index < 0 || index >= RB_DEVICES_N) {
        return NULL;
    }
    return &RB_DEVICES[index];
}

const rb_device *rb_device_by_id(const char *id)
{
    int i;

    if (id == NULL || id[0] == '\0') {
        return NULL;
    }
    for (i = 0; i < RB_DEVICES_N; i++) {
        if (strcmp(RB_DEVICES[i].id, id) == 0) {
            return &RB_DEVICES[i];
        }
    }
    return NULL;
}
